import csv, os, sys
out = sys.argv[1]
def w(name, header, rows):
    with open(os.path.join(out, name), "w", newline="", encoding="utf-8") as fh:
        cw = csv.writer(fh); cw.writerow(header); cw.writerows(rows)
    print(name, len(rows))

